import { test, expect } from '@playwright/test';

test.describe('Error Boundary - UI Crash Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/dashboard');
  });

  test('should display fallback screen when UI component crashes', async ({ page }) => {
    // Verify dashboard is visible
    const dashboard = page.getByRole('main');
    await expect(dashboard).toBeVisible();

    // Click on a component that is designed to crash
    const crashButton = page.getByRole('button', { name: /crash component/i });
    await crashButton.click();

    // Wait for error boundary to catch the crash
    await page.waitForTimeout(500);

    // Verify fallback screen is displayed
    const fallbackScreen = page.getByRole('region', { name: /fallback/i });
    await expect(fallbackScreen).toBeVisible();

    // Verify error message is visible
    const errorMessage = page.getByText(/an unexpected error occurred/i);
    await expect(errorMessage).toBeVisible();

    // Verify user can navigate away from fallback
    const navigateButton = page.getByRole('button', { name: /navigate away/i });
    await expect(navigateButton).toBeVisible();
    await navigateButton.click();

    // Verify user is back on dashboard
    await expect(dashboard).toBeVisible();
  });

  test('should not display fallback screen when component loads successfully', async ({ page }) => {
    // Verify dashboard is visible
    const dashboard = page.getByRole('main');
    await expect(dashboard).toBeVisible();

    // Verify crash button is not visible
    const crashButton = page.getByRole('button', { name: /crash component/i });
    await expect(crashButton).not.toBeVisible();

    // Verify fallback screen is not visible
    const fallbackScreen = page.getByRole('region', { name: /fallback/i });
    await expect(fallbackScreen).not.toBeVisible();

    // Verify error message is not visible
    const errorMessage = page.getByText(/an unexpected error occurred/i);
    await expect(errorMessage).not.toBeVisible();

    // Verify user can interact with dashboard elements
    const profileAvatar = page.getByRole('img', { name: /user profile/i });
    await expect(profileAvatar).toBeVisible();
    await profileAvatar.click();

    // Verify profile menu appears
    const profileMenu = page.getByRole('menu');
    await expect(profileMenu).toBeVisible();
  });
});
